1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #111827;
17	    color: #e5e7eb;
18	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board-wrap { position: relative; }
22	  .board {
23	    display: grid;
24	    grid-template-columns: repeat(10, 28px);
25	    grid-template-rows: repeat(20, 28px);
26	    gap: 1px;
27	    padding: 1px;
28	    background: #1f2937;
29	    border: 2px solid #374151;
30	  }
31	  .cell { width: 28px; height: 28px; background-color: #0b1020; }
32	  .mini {
33	    display: grid;
34	    grid-template-columns: repeat(4, 16px);
35	    grid-template-rows: repeat(2, 16px);
36	    gap: 1px;
37	    margin-bottom: 10px;
38	  }
39	  .mini-cell { width: 16px; height: 16px; background-color: transparent; }
40	  .p-I { background-color: #22d3ee; }
41	  .p-O { background-color: #facc15; }
42	  .p-T { background-color: #a855f7; }
43	  .p-S { background-color: #22c55e; }
44	  .p-Z { background-color: #ef4444; }
45	  .p-J { background-color: #3b82f6; }
46	  .p-L { background-color: #f97316; }
47	  .panel { width: 160px; }
48	  .stat { margin-bottom: 14px; }
49	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9ca3af; }
50	  .stat .value { font-size: 24px; font-weight: 600; font-variant-numeric: tabular-nums; }
51	  .help { font-size: 12px; color: #9ca3af; line-height: 1.6; margin-top: 12px; }
52	  .overlay {
53	    position: absolute;
54	    inset: 0;
55	    display: flex;
56	    flex-direction: column;
57	    align-items: center;
58	    justify-content: center;
59	    background: rgba(17, 24, 39, 0.8);
60	    font-size: 22px;
61	    font-weight: 600;
62	  }
63	  .overlay small { font-size: 13px; font-weight: 400; margin-top: 8px; color: #d1d5db; }
64	</style>
65	</head>
66	<body>
67	<div class="game">
68	  <div class="board-wrap">
69	    <div class="board" id="board" data-testid="board"></div>
70	    <div class="overlay" id="overlay" hidden>Game over<small>Press Enter to play again</small></div>
71	  </div>
72	  <div class="panel">
73	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
74	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
75	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
76	    <div class="stat"><div class="label">Next</div><div id="next"></div></div>
77	    <div class="help">
78	      ← → move<br>
79	      ↑ rotate<br>
80	      ↓ soft drop<br>
81	      Space hard drop<br>
82	      Enter new game
83	    </div>
84	  </div>
85	</div>
86	<script>
87	(function () {
88	  "use strict";
89	
90	  var ROWS = 20;
91	  var COLS = 10;
92	  var PREVIEW = 3;
93	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
94	
95	  // Spawn orientation of each piece inside its rotation box.
96	  var SHAPES = {
97	    I: ["....", "IIII", "....", "...."],
98	    O: ["OO", "OO"],
99	    T: [".T.", "TTT", "..."],
100	    S: [".SS", "SS.", "..."],
101	    Z: ["ZZ.", ".ZZ", "..."],
102	    J: ["J..", "JJJ", "..."],
103	    L: ["..L", "LLL", "..."]
104	  };
105	
106	  var LINE_POINTS = [0, 100, 300, 500, 800];
107	
108	  var state = {
109	    board: [],      // ROWS arrays of COLS chars: "." or a piece letter
110	    current: null,  // { type, matrix, row, col }
111	    next: [],
112	    bag: [],
113	    score: 0,
114	    level: 1,
115	    lines: 0,
116	    status: "running"
117	  };
118	
119	  var timer = null;
120	
121	  // ---------- pieces ----------
122	
123	  function isType(t) { return TYPES.indexOf(t) !== -1; }
124	
125	  function randomType() {
126	    if (state.bag.length === 0) {
127	      var bag = TYPES.slice();
128	      for (var i = bag.length - 1; i > 0; i--) {
129	        var j = Math.floor(Math.random() * (i + 1));
130	        var tmp = bag[i]; bag[i] = bag[j]; bag[j] = tmp;
131	      }
132	      state.bag = bag;
133	    }
134	    return state.bag.pop();
135	  }
136	
137	  function cleanQueue(queue) {
138	    if (!Array.isArray(queue)) return [];
139	    return queue.map(function (t) { return String(t).toUpperCase(); }).filter(isType);
140	  }
141	
142	  function fillPreview() {
143	    while (state.next.length < PREVIEW) state.next.push(randomType());
144	  }
145	
146	  function makeMatrix(type) {
147	    return SHAPES[type].map(function (r) { return r.split(""); });
148	  }
149	
150	  function pieceCells(piece) {
151	    var cells = [];
152	    for (var r = 0; r < piece.matrix.length; r++) {
153	      for (var c = 0; c < piece.matrix[r].length; c++) {
154	        if (piece.matrix[r][c] !== ".") cells.push([piece.row + r, piece.col + c]);
155	      }
156	    }
157	    return cells;
158	  }
159	
160	  function fits(matrix, row, col) {
161	    for (var r = 0; r < matrix.length; r++) {
162	      for (var c = 0; c < matrix[r].length; c++) {
163	        if (matrix[r][c] === ".") continue;
164	        var br = row + r, bc = col + c;
165	        if (br < 0 || br >= ROWS || bc < 0 || bc >= COLS) return false;
166	        if (state.board[br][bc] !== ".") return false;
167	      }
168	    }
169	    return true;
170	  }
171	
172	  // [REQ-001] Spawn the next piece at the top of the board.
173	  function spawn() {
174	    var type = state.next.length ? state.next.shift() : randomType();
175	    if (state.next.length === 0) fillPreview();
176	    var matrix = makeMatrix(type);
177	    var top = 0;
178	    while (matrix[top].every(function (ch) { return ch === "."; })) top++;
179	    var piece = {
180	      type: type,
181	      matrix: matrix,
182	      row: -top,
183	      col: Math.floor((COLS - matrix[0].length) / 2),
184	      lockTicks: 0,
185	      lockResets: 0
186	    };
187	    if (!fits(piece.matrix, piece.row, piece.col)) {
188	      state.current = null;
189	      state.status = "over";
190	      stopTimer();
191	      return;
192	    }
193	    state.current = piece;
194	  }
195	
196	  // ---------- core rules ----------
197	
198	  function clearLines() {
199	    var kept = state.board.filter(function (row) {
200	      return row.some(function (ch) { return ch === "."; });
201	    });
202	    var cleared = ROWS - kept.length;
203	    while (kept.length < ROWS) kept.unshift(emptyRow());
204	    state.board = kept;
205	    if (cleared > 0) {
206	      state.score += LINE_POINTS[cleared] * state.level;
207	      state.lines += cleared;
208	      state.level = Math.floor(state.lines / 10) + 1;
209	    }
210	  }
211	
212	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next one.
213	  function lockPiece() {
214	    var p = state.current;
215	    pieceCells(p).forEach(function (cell) {
216	      state.board[cell[0]][cell[1]] = p.type;
217	    });
218	    state.current = null;
219	    clearLines();
220	    spawn();
221	  }
222	
223	  function tryMove(dr, dc) {
224	    var p = state.current;
225	    if (!p || !fits(p.matrix, p.row + dr, p.col + dc)) return false;
226	    p.row += dr;
227	    p.col += dc;
228	    return true;
229	  }
230	
231	  // Lock rule (DEC): a gravity step that cannot move the piece down counts one tick of
232	  // lock delay; the piece locks on the LOCK_DELAY-th such tick. A left/right move while
233	  // resting restarts the delay, at most MAX_LOCK_RESETS times per piece.
234	  var LOCK_DELAY = 2;
235	  var MAX_LOCK_RESETS = 3;
236	
237	  function isResting(p) {
238	    return !fits(p.matrix, p.row + 1, p.col);
239	  }
240	
241	  // [REQ-002] One gravity step: fall one row, or count a tick of lock delay.
242	  // Used by the real timer, by tick(n) and by soft drop.
243	  function gravityStep() {
244	    if (state.status !== "running" || !state.current) return;
245	    var p = state.current;
246	    if (tryMove(1, 0)) {
247	      p.lockTicks = 0;
248	      return;
249	    }
250	    p.lockTicks++;
251	    if (p.lockTicks >= LOCK_DELAY) lockPiece();
252	  }
253	
254	  // [REQ-002] Sideways move; restarts the lock delay if the piece was resting.
255	  function shift(dc) {
256	    var p = state.current;
257	    var resting = isResting(p);
258	    if (!tryMove(0, dc)) return;
259	    if (resting && p.lockResets < MAX_LOCK_RESETS) {
260	      p.lockResets++;
261	      p.lockTicks = 0;
262	    }
263	  }
264	
265	  // [REQ-002] Clockwise rotation with sideways kicks; refused if nothing fits.
266	  function rotate() {
267	    var p = state.current;
268	    if (!p) return;
269	    var size = p.matrix.length;
270	    var rotated = [];
271	    for (var r = 0; r < size; r++) {
272	      rotated.push([]);
273	      for (var c = 0; c < size; c++) rotated[r].push(p.matrix[size - 1 - c][r]);
274	    }
275	    var kicks = [0, -1, 1, -2, 2];
276	    for (var i = 0; i < kicks.length; i++) {
277	      if (fits(rotated, p.row, p.col + kicks[i])) {
278	        p.matrix = rotated;
279	        p.col += kicks[i];
280	        return;
281	      }
282	    }
283	  }
284	
285	  // [REQ-001] Player actions.
286	  function input(action) {
287	    if (state.status !== "running" || !state.current) return;
288	    switch (action) {
289	      case "left": shift(-1); break;
290	      case "right": shift(1); break;
291	      case "softDrop": gravityStep(); break;
292	      case "hardDrop":
293	        while (tryMove(1, 0)) {}
294	        lockPiece();
295	        break;
296	      case "rotate":
297	      case "rotateCW": rotate(); break;
298	      default: return;
299	    }
300	    render();
301	    restartTimerIfNeeded();
302	  }
303	
304	  // ---------- timer ----------
305	
306	  function gravityInterval() {
307	    return Math.max(100, 1000 - (state.level - 1) * 90);
308	  }
309	
310	  function stopTimer() {
311	    if (timer !== null) { clearTimeout(timer); timer = null; }
312	  }
313	
314	  function startTimer() {
315	    stopTimer();
316	    if (state.status !== "running") return;
317	    timer = setTimeout(function () {
318	      timer = null;
319	      gravityStep();
320	      render();
321	      startTimer();
322	    }, gravityInterval());
323	  }
324	
325	  function restartTimerIfNeeded() {
326	    if (state.status === "running" && timer === null) startTimer();
327	  }
328	
329	  // ---------- setup ----------
330	
331	  function emptyRow() {
332	    var row = [];
333	    for (var c = 0; c < COLS; c++) row.push(".");
334	    return row;
335	  }
336	
337	  // [REQ-001] Start a fresh game, optionally with a fixed piece order.
338	  function newGame(queue) {
339	    state.board = [];
340	    for (var r = 0; r < ROWS; r++) state.board.push(emptyRow());
341	    state.bag = [];
342	    state.score = 0;
343	    state.level = 1;
344	    state.lines = 0;
345	    state.status = "running";
346	    state.current = null;
347	    var q = cleanQueue(queue);
348	    state.next = q;
349	    if (q.length === 0) fillPreview();
350	    spawn();
351	    render();
352	    startTimer();
353	  }
354	
355	  // ---------- rendering (synchronous) ----------
356	
357	  var boardEl = document.getElementById("board");
358	  var nextEl = document.getElementById("next");
359	  var scoreEl = document.getElementById("score");
360	  var levelEl = document.getElementById("level");
361	  var linesEl = document.getElementById("lines");
362	  var overlayEl = document.getElementById("overlay");
363	  var cellEls = [];
364	
365	  (function buildBoard() {
366	    for (var r = 0; r < ROWS; r++) {
367	      cellEls.push([]);
368	      for (var c = 0; c < COLS; c++) {
369	        var el = document.createElement("div");
370	        el.className = "cell";
371	        el.setAttribute("data-testid", "cell");
372	        el.setAttribute("data-row", String(r));
373	        el.setAttribute("data-col", String(c));
374	        el.setAttribute("data-filled", "false");
375	        el.setAttribute("data-piece", "");
376	        boardEl.appendChild(el);
377	        cellEls[r].push(el);
378	      }
379	    }
380	  })();
381	
382	  function paintCell(el, type) {
383	    el.className = type ? "cell p-" + type : "cell";
384	    el.setAttribute("data-filled", type ? "true" : "false");
385	    el.setAttribute("data-piece", type || "");
386	  }
387	
388	  function renderPreview() {
389	    nextEl.textContent = "";
390	    state.next.slice(0, PREVIEW).forEach(function (type) {
391	      var grid = document.createElement("div");
392	      grid.className = "mini";
393	      var rows = SHAPES[type].filter(function (r) { return r.indexOf(type) !== -1; });
394	      for (var r = 0; r < 2; r++) {
395	        for (var c = 0; c < 4; c++) {
396	          var cell = document.createElement("div");
397	          var ch = rows[r] ? rows[r].charAt(c) : ".";
398	          cell.className = ch === type ? "mini-cell p-" + type : "mini-cell";
399	          cell.setAttribute("data-piece", ch === type ? type : "");
400	          grid.appendChild(cell);
401	        }
402	      }
403	      nextEl.appendChild(grid);
404	    });
405	  }
406	
407	  // [REQ-001] Draw the whole game state into the DOM, immediately.
408	  function render() {
409	    var drawn = state.board.map(function (row) { return row.slice(); });
410	    if (state.current) {
411	      var type = state.current.type;
412	      pieceCells(state.current).forEach(function (cell) {
413	        drawn[cell[0]][cell[1]] = type;
414	      });
415	    }
416	    for (var r = 0; r < ROWS; r++) {
417	      for (var c = 0; c < COLS; c++) {
418	        var ch = drawn[r][c];
419	        paintCell(cellEls[r][c], ch === "." ? "" : ch);
420	      }
421	    }
422	    scoreEl.textContent = String(state.score);
423	    levelEl.textContent = String(state.level);
424	    linesEl.textContent = String(state.lines);
425	    overlayEl.hidden = state.status !== "over";
426	    renderPreview();
427	  }
428	
429	  // ---------- keyboard ----------
430	
431	  document.addEventListener("keydown", function (e) {
432	    var map = {
433	      ArrowLeft: "left",
434	      ArrowRight: "right",
435	      ArrowDown: "softDrop",
436	      ArrowUp: "rotateCW",
437	      " ": "hardDrop"
438	    };
439	    if (e.key === "Enter") {
440	      e.preventDefault();
441	      newGame();
442	      return;
443	    }
444	    if (map[e.key]) {
445	      e.preventDefault();
446	      input(map[e.key]);
447	    }
448	  });
449	
450	  // ---------- test control surface ----------
451	
452	  // [REQ-001]
453	  window.__tetris = {
454	    newGame: function (queue) { newGame(queue); },
455	    setQueue: function (queue) {
456	      state.next = cleanQueue(queue);
457	      render();
458	    },
459	    setBoard: function (rows) {
460	      var board = [];
461	      for (var r = 0; r < ROWS; r++) {
462	        var line = rows && typeof rows[r] === "string" ? rows[r] : "";
463	        var row = [];
464	        for (var c = 0; c < COLS; c++) {
465	          var ch = line.charAt(c);
466	          row.push(isType(ch) ? ch : ".");
467	        }
468	        board.push(row);
469	      }
470	      state.board = board;
471	      render();
472	    },
473	    tick: function (n) {
474	      var steps = n === undefined ? 1 : n;
475	      for (var i = 0; i < steps; i++) gravityStep();
476	      render();
477	    },
478	    input: function (action) { input(action); },
479	    getBoard: function () {
480	      return state.board.map(function (row) { return row.join(""); });
481	    },
482	    getState: function () {
483	      return {
484	        current: state.current
485	          ? { type: state.current.type, cells: pieceCells(state.current) }
486	          : null,
487	        next: state.next.slice(),
488	        score: state.score,
489	        level: state.level,
490	        lines: state.lines,
491	        status: state.status
492	      };
493	    }
494	  };
495	
496	  newGame();
497	})();
498	</script>
499	</body>
500	</html>
